import React, { createContext, useState, useContext, useEffect } from 'react';

export const CartContext = createContext();

export const CartProvider = ({ children }) => {
    const [cartItems, setCartItems] = useState(() => {
        const saved = localStorage.getItem('cart');
        return saved ? JSON.parse(saved) : [];
    });

    useEffect(() => {
        localStorage.setItem('cart', JSON.stringify(cartItems));
    }, [cartItems]);

    const addToCart = (product, supplierId, quantity = 1) => {
        setCartItems(prev => {
            const existing = prev.find(item =>
                item.productId === product._id && item.supplierId === supplierId
            );

            if (existing) {
                return prev.map(item =>
                    item.productId === product._id && item.supplierId === supplierId
                        ? { ...item, quantity: item.quantity + quantity }
                        : item
                );
            }

            return [...prev, {
                productId: product._id,
                supplierId,
                name: product.name,
                sku: product.sku,
                price: product.currentPrice,
                unit: product.unit,
                quantity,
                imageUrl: product.imageUrl,
                addedAt: new Date().toISOString()
            }];
        });
    };

    const removeFromCart = (productId, supplierId) => {
        setCartItems(prev =>
            prev.filter(item => !(item.productId === productId && item.supplierId === supplierId))
        );
    };

    const updateQuantity = (productId, supplierId, quantity) => {
        if (quantity < 1) {
            removeFromCart(productId, supplierId);
            return;
        }

        setCartItems(prev =>
            prev.map(item =>
                item.productId === productId && item.supplierId === supplierId
                    ? { ...item, quantity }
                    : item
            )
        );
    };

    const clearCart = () => {
        setCartItems([]);
    };

    const totalPrice = cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const totalItems = cartItems.reduce((sum, item) => sum + item.quantity, 0);

    return (
        <CartContext.Provider value={{
            cartItems,
            addToCart,
            removeFromCart,
            updateQuantity,
            clearCart,
            totalPrice,
            totalItems
        }}>
            {children}
        </CartContext.Provider>
    );
};
